4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.web.bind.annotation.RequestBody;
6	
7	/**
8	 * Canonicalizes the create-owner address to its normalized form (see {@link OwnerAddresses})
9	 * and publishes the request body for the rest of the pipeline. Runs first so the normalized
10	 * address flows into the required-field check, the household comparisons, storage and the
11	 * response.
12	 *
13	 * <p>Binds the request body once for the pipeline; later steps read it via {@code @Val}.
14	 */
15	public class NormalizeOwnerAddress {
16	
17	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> body) {
18	        request.setAddress(OwnerAddresses.normalize(request.getAddress()));
19	        body.set(request);
20	    }
21	}
