3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects a create-owner request that shares a household with an existing owner — same last
11	 * name and address once normalized (see {@link OwnerHouseholds}) — responding 409 via
12	 * {@link DuplicateHouseholdException}. A request that opts in with {@code sharesHousehold}
13	 * true is allowed through.
14	 */
15	public class RequireUniqueHousehold {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateHouseholdException {
19	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
20	            return;
21	        }
22	        String key = OwnerHouseholds.key(request.getLastName(), request.getAddress());
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (key.equals(OwnerHouseholds.key(existing.getLastName(), existing.getAddress()))) {
25	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
26	            }
27	        }
28	    }
29	}
