3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * When a create-owner request opts in with {@code sharesHousehold} true, assigns the new
10	 * owner and every existing owner in the same household — same last name and address once
11	 * normalized (see {@link OwnerHouseholds}) — the same stable {@code householdId}. A no-op
12	 * for a request that does not opt in.
13	 *
14	 * <p>Runs after {@link BuildOwner}, so it works with the built {@link Owner} entity and
15	 * relies on {@link RequireUniqueHousehold} having already allowed the shared household.
16	 */
17	public class AssignOwnerHousehold {
18	
19	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
20	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        String key = OwnerHouseholds.key(owner.getLastName(), owner.getAddress());
24	        String householdId = OwnerHouseholds.id(owner.getLastName(), owner.getAddress());
25	        owner.setHouseholdId(householdId);
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (key.equals(OwnerHouseholds.key(existing.getLastName(), existing.getAddress()))) {
28	                existing.setHouseholdId(householdId);
29	                ownerRepository.save(existing);
30	            }
31	        }
32	    }
33	}
