5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Establishes a new owner's effective registration date: defaulting to the server's current
10	 * date when the request did not supply one, then rolling a weekend date (whether supplied or
11	 * defaulted) forward to the next business day so the stored {@code registrationDate} always
12	 * falls on a weekday. Everything derived from it (e.g. the membership number's year segment,
13	 * the per-day create limit) therefore uses the adjusted date.
14	 */
15	public class ResolveOwnerRegistrationDate {
16	
17	    public void service(@Val Owner owner) {
18	        LocalDate effective = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
19	        owner.setRegistrationDate(BusinessDays.rollForward(effective));
20	    }
21	}
