1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.escalation.DailyRegistrationLimitException;
9	
10	/**
11	 * Rejects a create-owner request once the maximum number of owners ({@value #DAILY_LIMIT})
12	 * have already been registered on the new owner's (adjusted, business-day)
13	 * {@link Owner#getRegistrationDate() registrationDate}, responding 429 via
14	 * {@link DailyRegistrationLimitException}. Runs after the registration date has been
15	 * resolved so the count buckets by the same business day the new owner would be stored under.
16	 */
17	public class RequireDailyRegistrationCapacity {
18	
19	    /** Maximum owners that may be registered on a single business day; the request is rejected once reached. */
20	    static final int DAILY_LIMIT = 100;
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DailyRegistrationLimitException {
23	        LocalDate registrationDate = owner.getRegistrationDate();
24	        long registeredThatDay = ownerRepository.findAll().stream()
25	            .map(Owner::getRegistrationDate)
26	            .filter(registrationDate::equals)
27	            .count();
28	        if (registeredThatDay >= DAILY_LIMIT) {
29	            throw new DailyRegistrationLimitException(DAILY_LIMIT);
30	        }
31	    }
32	}
