3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Shared address canonicalization for the owner pipelines: reduces an address to a single
8	 * normalized form so the required-field check, household comparisons and storage all use
9	 * the same value.
10	 *
11	 * <p>Normalization trims surrounding whitespace, collapses each internal run of whitespace
12	 * to a single space, upper-cases, and expands common street-type abbreviations
13	 * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}) as whole words. It is
14	 * idempotent: normalizing an already-normalized address returns it unchanged.
15	 */
16	final class OwnerAddresses {
17	
18	    /** Whole-word abbreviation expansions, keyed by their upper-cased form. */
19	    private static final Map<String, String> ABBREVIATIONS = Map.of(
20	            "ST", "STREET",
21	            "RD", "ROAD",
22	            "AVE", "AVENUE");
23	
24	    private OwnerAddresses() {
25	    }
26	
27	    /**
28	     * Canonical form of {@code address}: trimmed, internal whitespace collapsed to single
29	     * spaces, upper-cased, with each abbreviation token expanded. A {@code null} address, or
30	     * one that is empty once trimmed, normalizes to {@code ""} (which the required-field check
31	     * then rejects as blank).
32	     */
33	    static String normalize(String address) {
34	        if (address == null) {
35	            return "";
36	        }
37	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
38	        if (collapsed.isEmpty()) {
39	            return "";
40	        }
41	        StringBuilder normalized = new StringBuilder(collapsed.length());
42	        for (String token : collapsed.split(" ")) {
43	            if (normalized.length() > 0) {
44	                normalized.append(' ');
45	            }
46	            normalized.append(ABBREVIATIONS.getOrDefault(token, token));
47	        }
48	        return normalized.toString();
49	    }
50	}
