3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Shared household identity for the create-owner pipeline: derives a canonical key from an
10	 * owner's last name and address so the duplicate-household check compares the same value.
11	 *
12	 * <p>Two owners share a household when their last names match case-insensitively (with
13	 * collapsed whitespace) and their addresses match once put through the shared
14	 * {@link OwnerAddresses#normalize(String) address normalization}.
15	 */
16	final class OwnerHouseholds {
17	
18	    private OwnerHouseholds() {
19	    }
20	
21	    /**
22	     * Canonical household key for {@code lastName} + {@code address}. Two requests/owners
23	     * belong to the same household exactly when their keys are equal.
24	     */
25	    static String key(String lastName, String address) {
26	        // '\n' separates the fields so "a b" + "c" cannot collide with "a" + "b c"
27	        // (a newline never survives whitespace collapsing).
28	        return normalizeLastName(lastName) + "\n" + OwnerAddresses.normalize(address);
29	    }
30	
31	    /**
32	     * Stable, shared household identifier for {@code lastName} + {@code address}, formatted
33	     * {@code HH-<12 hex>}. Derived from the canonical {@link #key(String, String)}, so every
34	     * owner in the same household resolves to the same value regardless of when they are
35	     * created.
36	     */
37	    static String id(String lastName, String address) {
38	        return "HH-" + sha256Hex(key(lastName, address)).substring(0, 12).toUpperCase(Locale.ROOT);
39	    }
40	
41	    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
42	    private static String sha256Hex(String value) {
43	        try {
44	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
45	            StringBuilder hex = new StringBuilder(digest.length * 2);
46	            for (byte b : digest) {
47	                hex.append(String.format("%02x", b));
48	            }
49	            return hex.toString();
50	        }
51	        catch (NoSuchAlgorithmException ex) {
52	            throw new IllegalStateException("SHA-256 not available", ex);
53	        }
54	    }
55	
56	    /** Trim, collapse internal whitespace runs to a single space, and lower-case. */
57	    private static String normalizeLastName(String value) {
58	        if (value == null) {
59	            return "";
60	        }
61	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
62	    }
63	}
