3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Registration dates must fall on a business day. A date landing on a Saturday or Sunday
8	 * rolls forward to the following Monday; a weekday is returned unchanged.
9	 */
10	final class BusinessDays {
11	
12	    private BusinessDays() {
13	    }
14	
15	    /** The given date if it is a weekday, otherwise the next Monday. */
16	    static LocalDate rollForward(LocalDate date) {
17	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
18	            date = date.plusDays(1);
19	        }
20	        return date;
21	    }
22	}
